CREATE TABLE pptx_document (id INTEGER PRIMARY KEY, schema TEXT NOT NULL, package_id INTEGER NOT NULL REFERENCES pptx_package(id));
CREATE TABLE pptx_package (id INTEGER PRIMARY KEY, comment TEXT NOT NULL);
CREATE TABLE pptx_binary_part (id INTEGER PRIMARY KEY, package_id INTEGER NOT NULL REFERENCES pptx_package(id), ordinal INTEGER NOT NULL CHECK(ordinal >= 0), path TEXT NOT NULL, content_type TEXT NOT NULL, data BLOB NOT NULL);
CREATE TABLE pptx_default_content_type (id INTEGER PRIMARY KEY, package_id INTEGER NOT NULL REFERENCES pptx_package(id), ordinal INTEGER NOT NULL CHECK(ordinal >= 0), extension TEXT NOT NULL, content_type TEXT NOT NULL);
CREATE TABLE pptx_override_content_type (id INTEGER PRIMARY KEY, package_id INTEGER NOT NULL REFERENCES pptx_package(id), ordinal INTEGER NOT NULL CHECK(ordinal >= 0), part_name TEXT NOT NULL, content_type TEXT NOT NULL);
CREATE TABLE pptx_relationship_owner (id INTEGER PRIMARY KEY, package_id INTEGER NOT NULL REFERENCES pptx_package(id), owner_path TEXT NOT NULL);
CREATE TABLE pptx_relationship (id INTEGER PRIMARY KEY, owner_id INTEGER NOT NULL REFERENCES pptx_relationship_owner(id), ordinal INTEGER NOT NULL CHECK(ordinal >= 0), identity TEXT NOT NULL, relation_type TEXT NOT NULL, target TEXT NOT NULL, target_mode TEXT NOT NULL CHECK(target_mode IN ('internal','external')));
CREATE TABLE pptx_xml_part (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES pptx_document(id), ordinal INTEGER NOT NULL CHECK(ordinal >= 0), content_type TEXT NOT NULL, xml_document_id INTEGER NOT NULL REFERENCES pptx_xml_document(id));
CREATE TABLE pptx_xml_document (id INTEGER PRIMARY KEY, path TEXT NOT NULL, root_node_id INTEGER REFERENCES pptx_xml_node(id));
CREATE TABLE pptx_xml_node (id INTEGER PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('element','text','cdata','comment','processing_instruction')));
CREATE TABLE pptx_xml_element (node_id INTEGER PRIMARY KEY REFERENCES pptx_xml_node(id), name TEXT NOT NULL);
CREATE TABLE pptx_xml_text (node_id INTEGER PRIMARY KEY REFERENCES pptx_xml_node(id), text TEXT NOT NULL);
CREATE TABLE pptx_xml_cdata (node_id INTEGER PRIMARY KEY REFERENCES pptx_xml_node(id), text TEXT NOT NULL);
CREATE TABLE pptx_xml_comment (node_id INTEGER PRIMARY KEY REFERENCES pptx_xml_node(id), text TEXT NOT NULL);
CREATE TABLE pptx_xml_processing_instruction (node_id INTEGER PRIMARY KEY REFERENCES pptx_xml_node(id), target TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE pptx_xml_attribute (id INTEGER PRIMARY KEY, element_node_id INTEGER NOT NULL REFERENCES pptx_xml_element(node_id), ordinal INTEGER NOT NULL CHECK(ordinal >= 0), name TEXT NOT NULL, value TEXT NOT NULL);
CREATE TABLE pptx_xml_child (id INTEGER PRIMARY KEY, parent_element_node_id INTEGER NOT NULL REFERENCES pptx_xml_element(node_id), ordinal INTEGER NOT NULL CHECK(ordinal >= 0), child_node_id INTEGER NOT NULL REFERENCES pptx_xml_node(id));
CREATE TABLE pptx_xml_document_misc (id INTEGER PRIMARY KEY, xml_document_id INTEGER NOT NULL REFERENCES pptx_xml_document(id), position TEXT NOT NULL CHECK(position IN ('prolog','epilog')), ordinal INTEGER NOT NULL CHECK(ordinal >= 0), node_id INTEGER NOT NULL REFERENCES pptx_xml_node(id));
CREATE TABLE pptx_xml_declaration (id INTEGER PRIMARY KEY, xml_document_id INTEGER NOT NULL REFERENCES pptx_xml_document(id), version TEXT NOT NULL, encoding TEXT, standalone INTEGER CHECK(standalone IN (0,1)), quote TEXT NOT NULL CHECK(quote IN ('double','single')));
CREATE TABLE pptx_xml_doctype (id INTEGER PRIMARY KEY, xml_document_id INTEGER NOT NULL REFERENCES pptx_xml_document(id), prolog_position_decimal TEXT NOT NULL, name TEXT NOT NULL, external_kind TEXT CHECK(external_kind IN ('system','public')), public_id TEXT, system_id TEXT, CHECK((external_kind IS NULL AND public_id IS NULL AND system_id IS NULL) OR (external_kind = 'system' AND public_id IS NULL AND system_id IS NOT NULL) OR (external_kind = 'public' AND public_id IS NOT NULL AND system_id IS NOT NULL)));
CREATE TABLE pptx_xml_entity (id INTEGER PRIMARY KEY, doctype_id INTEGER NOT NULL REFERENCES pptx_xml_doctype(id), ordinal INTEGER NOT NULL CHECK(ordinal >= 0), parameter INTEGER NOT NULL CHECK(parameter IN (0,1)), name TEXT NOT NULL, value TEXT NOT NULL);
